        return sqrt((x2 - x1)**2 + (y2 - y1)**2)

    def move(x, y, vx, vy, wx, wy, dt):
        return x + dt * (vx + wx), y + dt * (vy + wy)

    tx = abs(x2 - x1)
    ty = abs(y2 - y1)
    time = 0

    for i in range(2 * t):
        wx, wy = winds[i // t][i % t]
        dt = min(vmax / sqrt(wx**2 + wy**2), min(tx, ty))
        x1, y1 = move(x1, y1, 0, 0, wx, wy, dt)
        tx -= dt
        ty -= dt
        time += dt

    return time + max(tx, ty)

